INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `VerifiedBuild`) VALUES
(4511, 'ruRU', 'Затишье перед бурей', 'Отнеси банковский ваучер Карусу в банк Оргриммара.', '$n, мы бы не зашли так далеко без тебя. Время, несомненно, скоро придёт, когда я снова попрошу твоей помощи против силитидов. Нам нужно осмыслить то, что мы узнали в Ун''Горо; боюсь, мои предположения о том, что силитиды произошли из Ун''Горо, теперь ошибочны... на самом деле где-то существует гораздо более сильное присутствие.$B$BОтнеси эту записку Карусу в банк. Он даст тебе что-то из моего хранилища в знак моей благодарности. Спасибо за помощь, могучий $c.', 22995),
